@js:
sort=[];
push=(title,url,type1,type2)=>
	sort.push({
	title: title,
	url: url,
	style: {
		layout_flexGrow: type1,
		layout_flexBasisPercent: type2
	}
});

area1=["中","港","美","日","韩"];
area1_id=["2","5","6","18","17"];
kind1=["伦理","动作","喜剧","科幻","恐怖","犯罪","战争","动漫","剧情","纪录","悬疑","动画","其他"];
kind1_id=["33","5","6","8","9","10","11","12","13","30","34","35","48"];

push('🚫动漫🚫','',1,1)
area2=["中","日"];
area2_id=["26","86"];
for(j=0;j<area2.length;j++){
	var title=area2[j];
	var url=`/p/4/c/${area2_id[j]}?page={{page}}`
	push(title,url,1,0.12)
}

push('🚫剧集🚫','',1,1)
area2_id=["19","20","22","83","82"];
for(j=0;j<area1.length;j++){
	var title=area1[j];
	var url=`/p/3/c/${area2_id[j]}?page={{page}}`
	push(title,url,1,0.12)
}

push('🚫综艺🚫','',1,1)
area3_id=["15","88","18","90","91"];
for(j=0;j<area1.length;j++){
	var title=area1[j];
	var url=`/p/4/c/${area3_id[j]}?page={{page}}`
	push(title,url,1,0.12)
}
push('🚫短剧🚫','',1,1)
area4=["爽剧","言情","穿越","悬疑","古装","都市","甜宠","恋爱"];
area4_id=["67","68","70","71","73","80","84","85"];
for(j=0;j<area4.length;j++){
	var title=area4[j];
	var url=`/p/3/c/${area4_id[j]}?page={{page}}`
	push(title,url,1,0.2)
}

push('🚫电影(每行为1类)🚫','',1,1)
for(i=0;i<kind1.length;i++){
	 push(kind1[i],`/p/1/c/${kind1_id[i]}?page={{page}}`,1,0.16)
	 for(j=0;j<area1.length;j++){
	 	 var title=area1[j];
	 	 var url=`/p/1/c/${kind1_id[i]}?area_id=${area1_id[j]}&page={{page}}`
		 push(title,url,1,0.12)
	 }
}

java.log(JSON.stringify(sort))

