source.jsLib:
//●下面是格式化函数
function formatResult(result) {
  const clickMatch = result.match(/总点击：([\d,.]+)万/);
  const collectMatch = result.match(/总收藏：([\d,]+)/);
  const wordMatch = result.match(/总字数：([\d,]+)/);

  if (!clickMatch || !collectMatch || !wordMatch) {
    return result;
  }
  const clickStr = clickMatch[1].replace(/,/g, '');
  const collectStr = collectMatch[1].replace(/,/g, '');
  const wordStr = wordMatch[1].replace(/,/g, '');
  const clickNum = parseFloat(clickStr);
  const collectNum = parseInt(collectStr);
  const wordNum = parseInt(wordStr);
  const formatNumber = (num) => {
    if (num >= 10000) {
      return (num / 10000).toFixed(1) + '万';
    }
    return num;
  };
  const formattedClick = `${clickNum.toFixed(1)}万`;
  const formattedCollect = formatNumber(collectNum);
  const formattedWord = formatNumber(wordNum);
  return `总字数：${formattedWord} 总点击：${formattedClick} 总收藏：${formattedCollect}`;
}

